const z = require("zod");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const schema = z.record(z.enum(["a", "b"]).refine((k) => k === "a", "key must be a"), z.string());
const bad = schema.safeParse({ a: "x", b: "y" });
if (bad.success) symptom("z.record with an enum key ignored the key refinement and accepted key b");
const iss = bad.error.issues;
if (iss.length !== 1 || iss[0].code !== "invalid_key" || iss[0].path.join() !== "b") broken("unexpected issues: " + JSON.stringify(iss));
console.log("OK: key refinement failure surfaced as invalid_key at path b");

